  "n.act1.a": [N, "narrator/batch1/n.act1.a.mp3", "他走進了魔法花園。花香香的。"],
  "n.act1.b": [N, "narrator/batch1/n.act1.b.mp3", "花園的燈，我先點好了。"],
  "n.act2.a": [N, "narrator/batch1/n.act2.a.mp3", "往上，是燈籠書庫。書在發光。"],
  "n.act2.b": [N, "narrator/batch1/n.act2.b.mp3", "書庫好安靜，書在說悄悄話。"],
  "n.act3.a": [N, "narrator/batch1/n.act3.a.mp3", "再往上，是星空觀星台。"],
  "n.act3.b": [N, "narrator/batch1/n.act3.b.mp3", "好高了。抬頭，就是星星。"],
  "n.boss.near.a": [N, "narrator/batch1/n.boss.near.a.mp3", "前面，有個大守衛在睡覺。"],
  "n.boss.near.b": [N, "narrator/batch1/n.boss.near.b.mp3", "樓梯上，傳來好大的呼嚕聲。"],
  "n.boss.poof": [N, "narrator/batch1/n.boss.poof.mp3", "大守衛暈了，變成滿天音符。"],
  "n.boss1.in": [N, "narrator/batch1/n.boss1.in.mp3", "塔守護獸醒了，只記得要擋路。"],
  "n.boss1.ph": [N, "narrator/batch1/n.boss1.ph.mp3", "守護獸打了個大噴嚏！"],
  "n.boss2.in": [N, "narrator/batch1/n.boss2.in.mp3", "雙翼監守醒了，要大家安靜。"],
  "n.boss2.ph": [N, "narrator/batch1/n.boss2.ph.mp3", "牠拍起翅膀，書都飛起來了。"],
  "n.boss3.in": [N, "narrator/batch1/n.boss3.in.mp3", "終焉王醒了，戴好他的王冠。"],
  "n.boss3.ph": [N, "narrator/batch1/n.boss3.ph.mp3", "王冠歪了，大王有點急了。"],
  "n.camp.rest": [N, "narrator/batch1/n.camp.rest.mp3", "他坐在營火旁，暖暖的。"],
  "n.camp.up": [N, "narrator/batch1/n.camp.up.mp3", "他把一張牌，練得更亮了。"],
  "n.clear.a": [N, "narrator/batch1/n.clear.a.mp3", "這一層的燈，全亮了。"],
  "n.clear.b": [N, "narrator/batch1/n.clear.b.mp3", "往上的樓梯，我點好燈了。"],
  "n.faint.a": [N, "narrator/batch1/n.faint.a.mp3", "累了，就躺一下吧。塔會等。"],
  "n.faint.b": [N, "narrator/batch1/n.faint.b.mp3", "頭好暈，他躺下來休息。"],
  "n.fight.big.a": [N, "narrator/batch1/n.fight.big.a.mp3", "好大一擊！燈都晃了。"],
